55	const BASE_PREMIUMS: Record<string, number> = {
56	  sword: 100,
57	  amulet: 60,
58	  staff: 80,
59	  potion: 40,
60	  rune: 25,
61	  moonstone: 25,
62	};
63	
64	/**
65	 * Insurance values are distinct from base premiums: they size the payout cap,
66	 * not the price. Component block discounts affect the premium only, never the
67	 * insurance sum, so this table is always applied per individual item.
68	 */
69	const INSURANCE_VALUES: Record<string, number> = {
70	  sword: 1000,
71	  amulet: 600,
72	  staff: 800,
73	  potion: 400,
74	  rune: 250,
75	  moonstone: 250,
76	};
77	
78	const DEDUCTIBLE_PER_DAMAGE = 100;
79	const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
80	
81	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
82	const PROCESSING_FEE = 5;
83	
84	const HUNDRED = 100;
85	
86	/**
87	 * The value of a percentage of an amount. Modifiers are summed as separate
88	 * amounts rather than compounded, so each is computed against its own base:
89	 * a cursed sword is 100 + 50 % of 100 + 10 % of 100, not 100 × 1.5 × 1.1.
90	 *
91	 * Multiplies before dividing, keeping the percentage an integer ratio rather
92	 * than a decimal factor: 100 * 1.1 === 110.00000000000001 in binary floating
93	 * point, which would round the wrong way. Intermediates stay exact and only
94	 * the final premium is rounded.
95	 */
96	const percentOf = (amount: number, percent: number): number =>
97	  (amount * percent) / HUNDRED;
98	
99	/** Premiums are rounded up — in the MHPCO's favour. */
100	const roundPremium = (amount: number): number => Math.ceil(amount);
101	
102	const basePremiumOfType = (type: string): number => {
103	  const basePremium = BASE_PREMIUMS[type];
104	  if (basePremium === undefined) {
105	    // The spec rejects a quote containing an unknown item type outright, but
106	    // no active test pins the error behaviour yet. Fail loudly rather than
107	    // silently pricing an unknown item at zero, which the spec contradicts.
108	    throw new Error(`Unknown item type: ${type}`);
109	  }
110	  return basePremium;
111	};
112	
113	/** Component types are sold individually or as a block of alike pieces. */
114	const COMPONENT_TYPES = ["rune", "moonstone"];
115	const COMPONENT_BLOCK_SIZE = 3;
116	const COMPONENT_BLOCK_PREMIUM = 60;
117	
118	const countByType = (items: Item[]): Map<string, number> => {
119	  const counts = new Map<string, number>();
120	  for (const item of items) {
121	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
122	  }
123	  return counts;
124	};
125	
126	/**
127	 * Base premium for a group of alike items. A block rate applies only when a
128	 * component type appears exactly COMPONENT_BLOCK_SIZE times — blocks do not
129	 * repeat, so 4 runes cost 4 singles rather than a block plus a single.
130	 */
131	const basePremiumOfGroup = (type: string, count: number): number => {
132	  if (COMPONENT_TYPES.includes(type) && count === COMPONENT_BLOCK_SIZE) {
133	    return COMPONENT_BLOCK_PREMIUM;
134	  }
135	  return count * basePremiumOfType(type);
136	};
137	
138	const CURSE_SURCHARGE_PERCENT = 50;
139	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
140	const HIGH_ENCHANTMENT_MIN_LEVEL = 5;
141	
142	/**
143	 * Whether an item carries an enchantment at or above the surcharge threshold.
144	 * Components (runes, moonstones) have no enchantment field at all; an absent
145	 * enchantment is not a level of 0, it is the absence of the property, and so
146	 * never qualifies. Stated as an explicit undefined check rather than a numeric
147	 * default so the reason reads as "unenchanted", not "enchanted to zero".
148	 */
149	const isHighlyEnchanted = (item: Item): boolean =>
150	  item.enchantment !== undefined && item.enchantment >= HIGH_ENCHANTMENT_MIN_LEVEL;
151	
152	/**
153	 * Item-specific surcharges are a percentage of the affected item's OWN base
154	 * premium, not of the policy total. They are summed alongside the policy-wide
155	 * modifiers rather than compounded with them, so an item that is both cursed
156	 * and highly enchanted carries base + 50 % of base + 30 % of base.
157	 *
158	 * KNOWN GAP: basePremiumOfType gives the item's standalone base, which differs
159	 * from its share of a component block — a rune in a block of 3 is charged 20,
160	 * not 25, so a cursed or highly enchanted rune inside a block would surcharge
161	 * against 25. This affects both surcharge terms, not just the curse. Left as
162	 * is deliberately: the spec defines neither cursed nor enchanted components,
163	 * gives no rule for apportioning a block rate across its pieces, and no test
164	 * pins the behaviour. Resolve it when a test forces a choice, not before.
165	 */
166	const itemSurchargeOf = (item: Item): number => {
167	  const itemBase = basePremiumOfType(item.type);
168	  const curseSurcharge =
169	    item.cursed === true ? percentOf(itemBase, CURSE_SURCHARGE_PERCENT) : 0;
170	  const enchantmentSurcharge = isHighlyEnchanted(item)
171	    ? percentOf(itemBase, HIGH_ENCHANTMENT_SURCHARGE_PERCENT)
172	    : 0;
173	  return curseSurcharge + enchantmentSurcharge;
174	};
175	
176	const LOYALTY_DISCOUNT_PERCENT = 20;
177	const LOYALTY_MIN_YEARS = 2;
178	
179	const FOLLOW_UP_DISCOUNT_PERCENT = 15;
180	
181	/**
182	 * Quotes are numbered from this ordinal; every quote after it is a follow-up
183	 * contract. The ordinal counts QUOTE steps only — claim steps interleave with
184	 * quotes in a scenario and must not advance the contract count.
185	 */
186	const FIRST_QUOTE_ORDINAL = 0;
187	
188	/** Long-standing customers qualify from exactly LOYALTY_MIN_YEARS onwards. */
189	const isLongStanding = (customer: Customer): boolean =>
190	  customer.yearsWithMHPCO >= LOYALTY_MIN_YEARS;
191	
192	/** Every contract after the customer's first one in the scenario. */
193	const isFollowUpContract = (quoteOrdinal: number): boolean =>
194	  quoteOrdinal > FIRST_QUOTE_ORDINAL;
195	
196	/** Policy base premium: every group's base, before any modifier. */
197	const policyBaseOf = (items: Item[]): number =>
198	  [...countByType(items)].reduce(
199	    (total, [type, count]) => total + basePremiumOfGroup(type, count),
200	    0,
201	  );
202	
203	const itemSurchargesOf = (items: Item[]): number =>
204	  items.reduce((total, item) => total + itemSurchargeOf(item), 0);
205	
206	/**
207	 * The net of the policy-wide modifiers: surcharges positive, discounts
208	 * negative. Each is a percentage of the POLICY base and they are summed, never
209	 * compounded — a long-standing customer's first insurance is +10 % and -20 % of
210	 * the same base, a net -10 %, not 1.1 × 0.8.
211	 */
212	const policyModifiersOf = (
213	  policyBase: number,
214	  customer: Customer,
215	  quoteOrdinal: number,
216	): number => {
217	  const firstInsuranceSurcharge = percentOf(
218	    policyBase,
219	    FIRST_INSURANCE_SURCHARGE_PERCENT,
220	  );
221	  const loyaltyDiscount = isLongStanding(customer)
222	    ? percentOf(policyBase, LOYALTY_DISCOUNT_PERCENT)
223	    : 0;
224	  const followUpDiscount = isFollowUpContract(quoteOrdinal)
225	    ? percentOf(policyBase, FOLLOW_UP_DISCOUNT_PERCENT)
226	    : 0;
227	  return firstInsuranceSurcharge - loyaltyDiscount - followUpDiscount;
228	};
229	
230	const quoteResult = (
231	  items: Item[],
232	  customer: Customer,
233	  quoteOrdinal: number,
234	): QuoteResult => {
235	  const policyBase = policyBaseOf(items);
236	  const premium =
237	    policyBase +
238	    itemSurchargesOf(items) +
239	    policyModifiersOf(policyBase, customer, quoteOrdinal) +
240	    PROCESSING_FEE;
241	  return { premium: roundPremium(premium) };
242	};
243	
244	/** A quote step's policy, carried forward so later claims can draw on it. */
245	interface Policy {
246	  items: Item[];
247	  remainingCap: number;
248	}
249	
250	const policyFor = (items: Item[]): Policy => {
251	  const insuranceSum = items.reduce(
252	    (total, item) => total + (INSURANCE_VALUES[item.type] ?? 0),
253	    0,
254	  );
255	  return {
256	    items,
257	    remainingCap: CAP_MULTIPLE_OF_INSURANCE_SUM * insuranceSum,
258	  };
259	};
260	
261	const HIGH_ENCHANTMENT_CLAUSE_MIN_LEVEL = 8;
262	const HIGH_ENCHANTMENT_CLAUSE_PERCENT = 50;
263	
264	/**
265	 * The damaged item, located by type. A damage entry names a TYPE, not a
266	 * particular item, so a policy holding two swords of different enchantments is
267	 * ambiguous; the spec offers no tie-break, so the first match wins.
268	 */
269	const damagedItem = (damage: Damage, items: Item[]): Item | undefined =>
270	  items.find((item) => item.type === damage.itemType);
271	
272	/**
273	 * One damage event. A special clause reduces the reimbursed amount BEFORE the
274	 * deductible is taken: an item enchanted to HIGH_ENCHANTMENT_CLAUSE_MIN_LEVEL
275	 * or above is reimbursed at half, so 1000 becomes 500 and then 400 — not
276	 * (1000 - 100) halved.
277	 *
278	 * DRAGON MATERIAL, deliberately unexpressed. The spec states a second clause —
279	 * damage to dragon-material items is FULLY reimbursed — which this function
280	 * never mentions. That is considered, not overlooked. Full reimbursement is
281	 * already the default path when no clause fires, so a dragon branch returning
282	 * damage.amount would be a branch no test could ever distinguish from its own
283	 * absence. The three spec cases pass unchanged: dragon/ench 8/1000 -> 400,
284	 * dragon/ench 5/800 -> 700, dragon/ench 9/1000 -> 400.
285	 *
286	 * The clauses also do not conflict in the way "both apply" suggests. Where an
287	 * item is both dragon and enchanted >= 8, the spec has the 50 % rule WIN — so
288	 * the enchantment check above is not merely first, it is correct to be the
289	 * only check. Should a later rule ever make full reimbursement differ from the
290	 * default (a cap interaction, say), this clause must become explicit.
291	 */
292	const payoutForDamage = (damage: Damage, items: Item[]): number => {
293	  const item = damagedItem(damage, items);
294	  const enchantment = item?.enchantment;
295	  const reimbursed =
296	    enchantment !== undefined &&
297	    enchantment >= HIGH_ENCHANTMENT_CLAUSE_MIN_LEVEL
298	      ? percentOf(damage.amount, HIGH_ENCHANTMENT_CLAUSE_PERCENT)
299	      : damage.amount;
300	  return reimbursed - DEDUCTIBLE_PER_DAMAGE;
301	};
302	
303	/**
304	 * A claim's effect on its policy: what is paid now and what the policy has
305	 * left afterwards. Pure — the caller is responsible for storing the new
306	 * remaining cap, so the arithmetic can be read (and later clipped to the cap)
307	 * without tracing who mutated what.
308	 */
309	const claimOutcome = (incident: Incident, policy: Policy): ClaimResult => {
310	  const desired = incident.damages.reduce(
311	    (total, damage) => total + payoutForDamage(damage, policy.items),
312	    0,
313	  );
314	  // The policy pays at most what its cap has left, so a claim beyond the cap is
315	  // reduced to the remainder and an exhausted policy pays nothing — the cap
316	  // lands on 0 rather than going negative.
317	  const payout = Math.min(desired, policy.remainingCap);
318	  return { payout, remainingCap: policy.remainingCap - payout };
319	};
320	
321	/**
322	 * Where a step sits in the scenario walk. The two ordinals are genuinely
323	 * different facts and must not be collapsed: `index` is the step's own
324	 * zero-based position, which is how a later claim names its policy, while
325	 * `quoteOrdinal` counts QUOTE steps only. In [quote, claim, quote] the last
326	 * step has index 2 but quote ordinal 1 — using either in place of the other
327	 * would misprice the follow-up discount.
328	 */
329	interface StepPosition {
330	  index: number;
331	  quoteOrdinal: number;
332	}
333	
334	/** The mutable state carried along one scenario: the policies quotes create. */
335	interface ScenarioWalk {
336	  customer: Customer;
337	  policies: Map<number, Policy>;
338	}
339	
340	const runStep = (
341	  step: Step,
342	  position: StepPosition,
343	  walk: ScenarioWalk,
344	): StepResult => {
345	  if (step.op === "quote") {
346	    walk.policies.set(position.index, policyFor(step.items));
347	    return quoteResult(step.items, walk.customer, position.quoteOrdinal);
348	  }
349	  const policy = walk.policies.get(step.policy);
350	  if (policy === undefined) {
351	    throw new Error(`No policy created by step ${step.policy}`);
352	  }
353	  const outcome = claimOutcome(step.incident, policy);
354	  policy.remainingCap = outcome.remainingCap;
355	  return outcome;
356	};
357	
358	export const runScenario = (scenario: Scenario): ScenarioResults => {
359	  const walk: ScenarioWalk = {
360	    customer: scenario.customer,
361	    policies: new Map<number, Policy>(),
362	  };
363	  let quoteOrdinal = FIRST_QUOTE_ORDINAL;
364	  const results = scenario.steps.map((step, index) => {
365	    const result = runStep(step, { index, quoteOrdinal }, walk);
366	    if (step.op === "quote") quoteOrdinal += 1;
367	    return result;
368	  });
369	  return { results };
370	};
371

